package com.jadhavr.erp.academic.controller;
import com.jadhavr.erp.admission.dto.AdmissionResponse; import com.jadhavr.erp.admission.entity.*; import com.jadhavr.erp.admission.enums.*; import com.jadhavr.erp.admission.mapper.AdmissionMapper; import com.jadhavr.erp.admission.repository.*; import com.jadhavr.erp.auth.security.*; import com.jadhavr.erp.common.api.ApiResponse; import com.jadhavr.erp.common.exception.*; import com.jadhavr.erp.student.enums.StudentStatus; import com.jadhavr.erp.student.repository.StudentProfileRepository; import com.jadhavr.erp.user.repository.UserRepository; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.security.access.AccessDeniedException; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*;
@RestController @RequestMapping("/api/principal/final-admissions") public class PrincipalFinalAdmissionController { private final AdmissionFormRepository admissions;private final AdmissionStatusHistoryRepository histories;private final StudentProfileRepository students;private final UserRepository users;private final AdmissionMapper mapper;public PrincipalFinalAdmissionController(AdmissionFormRepository a,AdmissionStatusHistoryRepository h,StudentProfileRepository s,UserRepository u,AdmissionMapper m){admissions=a;histories=h;students=s;users=u;mapper=m;} public record Approve(@Size(max=500)String remarks){} public record Reject(@NotBlank @Size(min=5,max=500)String rejectionReason){}
 @GetMapping("/review-ready") public ApiResponse<?> queue(@RequestParam(required=false)String keyword,@RequestParam(required=false)Long departmentId){List<AdmissionResponse> data=admissions.findAll().stream().filter(a->a.getStatus()==AdmissionStatus.PRINCIPAL_REVIEW_PENDING&&scope(a)&&(departmentId==null||departmentId.equals(a.getDepartment().getId()))&&(keyword==null||keyword.isBlank()||a.getFullName().toLowerCase().contains(keyword.toLowerCase())||a.getAdmissionReferenceNumber().toLowerCase().contains(keyword.toLowerCase()))).map(mapper::toResponse).toList();return ApiResponse.success("Final review queue",data);} @GetMapping("/{id}") public ApiResponse<?> get(@PathVariable Long id){var a=find(id);return ApiResponse.success("Admission detail",mapper.toResponse(a));}
 @PatchMapping("/{id}/approve") @Transactional public ApiResponse<?> approve(@PathVariable Long id,@Valid @RequestBody Approve r){AdmissionForm a=ready(id);var s=a.getStudent();if(s.getRollNumber()==null){String base="ROLL-%s-%s-".formatted(a.getCollege().getCode().toUpperCase(),a.getAcademicYear().replaceAll("[^0-9]",""));long n=students.findByCollegeId(a.getCollege().getId()).size()+1;String roll;do{roll=base+"%06d".formatted(n++);}while(students.existsByRollNumber(roll));s.setRollNumber(roll);}s.setStatus(StudentStatus.ACTIVE);s.setActivatedAt(LocalDateTime.now());students.save(s);change(a,AdmissionStatus.PRINCIPAL_APPROVED,AdmissionAction.PRINCIPAL_APPROVED,r.remarks());a.setPrincipalApprovedAt(LocalDateTime.now());return ApiResponse.success("Admission approved",mapper.toResponse(a));}
 @PatchMapping("/{id}/reject") @Transactional public ApiResponse<?> reject(@PathVariable Long id,@Valid @RequestBody Reject r){AdmissionForm a=ready(id);a.getStudent().setStatus(StudentStatus.ADMISSION_REJECTED);students.save(a.getStudent());a.setRejectionReason(r.rejectionReason().trim());change(a,AdmissionStatus.PRINCIPAL_REJECTED,AdmissionAction.PRINCIPAL_REJECTED,r.rejectionReason());return ApiResponse.success("Admission rejected",mapper.toResponse(a));}
 private AdmissionForm ready(Long id){AdmissionForm a=find(id);if(a.getStatus()!=AdmissionStatus.PRINCIPAL_REVIEW_PENDING)throw new BadRequestException("Admission is not ready for principal review");return a;} private AdmissionForm find(Long id){AdmissionForm a=admissions.findById(id).orElseThrow(()->new ResourceNotFoundException("Admission not found"));if(!scope(a))throw new AccessDeniedException("Admission is outside your college");return a;} private boolean scope(AdmissionForm a){return SecurityUtils.isSuperAdmin()||a.getCollege().getId().equals(SecurityUtils.requireCurrentUser().getCollegeId());} private void change(AdmissionForm a,AdmissionStatus status,AdmissionAction action,String remarks){AdmissionStatus old=a.getStatus();a.setStatus(status);admissions.save(a);AdmissionStatusHistory h=new AdmissionStatusHistory();h.setAdmissionForm(a);h.setChangedBy(users.findById(SecurityUtils.requireCurrentUser().getId()).orElse(null));h.setOldStatus(old);h.setNewStatus(status);h.setAction(action);h.setRemarks(remarks);histories.save(h);}
}
